<template><div class="heading-row"><div><div class="eyebrow">{{dateLabel}} <span class="live-dot"></span> LIVE</div><h1>Good morning, {{userName}} <span>âœ¦</span></h1><p>Here's what's happening with your inventory today.</p></div><div class="heading-actions"><button class="button secondary" @click="load"><RefreshCw :size="15" :class="{'spin':loading}"/> Refresh</button><button class="button primary" @click="router.push('/products')"><Plus :size="16"/> Add product</button></div></div><div v-if="error" class="error-banner"><WifiOff :size="17"/><span>Couldnâ€™t connect to the inventory API. Start the services with <code>docker compose up</code> to see live data.</span><button @click="load">Retry</button></div><div class="kpi-grid"><article class="kpi-card" v-for="k in metrics" :key="k.label"><div class="kpi-top"><span>{{k.label}}</span><div class="kpi-icon" :class="k.tone"><component :is="k.icon" :size="17"/></div></div><div class="kpi-value">{{loading?'â€”':k.value}}</div><div class="kpi-foot"><span v-if="k.change" class="change"><ArrowUpRight :size="13"/> {{k.change}}</span><span v-else-if="k.alert" class="change neutral"><AlertTriangle :size="13"/> {{k.alert}}</span><span class="foot-text">{{k.caption}}</span></div></article></div><div class="analytics-grid"><article class="card sales-card"><div class="card-header"><div><h2>Sales overview</h2><p>Revenue performance over time</p></div><div class="range-inputs"><label>From<input type="date" v-model="startDate" :max="endDate" @change="load"/></label><label>To<input type="date" v-model="endDate" :min="startDate" @change="load"/></label></div></div><div class="sales-total">{{fmt(dashboard?.revenue||0)}} </div><div class="chart-box"><canvas ref="salesCanvas"></canvas></div><div class="chart-legend"><span><i class="legend-dot blue"></i>This period</span><span><i class="legend-dot pale"></i>Last period</span></div></article><article class="card stock-card"><div class="card-header"><div><h2>Stock by category</h2><p>Current inventory distribution</p></div><button class="dots"><MoreHorizontal :size="18"/></button></div><div class="donut-wrap"><canvas ref="donutCanvas"></canvas><div class="donut-center"><b>{{fmtNum(dashboard?.totalProducts||0)}}</b><small>products</small></div></div><div class="category-list"><div v-for="cat in dashboard?.categories||[]" :key="cat.name"><span><i class="legend-dot" :style="{background:cat.color}"></i>{{cat.name}}</span><b>{{cat.value}}%</b></div><div v-if="!dashboard?.categories?.length" class="empty-mini">No category data available</div></div></article></div><div class="lower-grid"><article class="card table-card"><div class="card-header"><div><h2>Top products</h2><p>Your best performing products this month</p></div><RouterLink class="text-link" to="/products">View all <ArrowRight :size="14"/></RouterLink></div><div class="table-scroll"><table><thead><tr><th>PRODUCT</th><th>SKU</th><th>CATEGORY</th><th>STOCK</th><th>PRICE</th><th>STATUS</th></tr></thead><tbody><tr v-for="p in dashboard?.products||[]" :key="p.id"><td><div class="product-cell"><div class="product-icon"><Package :size="16"/></div><b>{{p.name}}</b></div></td><td class="code">{{p.sku}}</td><td>{{p.category}}</td><td><span :class="{'low-stock':p.stock<=p.reorderLevel}">{{p.stock}}</span></td><td>{{fmt(p.price)}}</td><td><span class="status" :class="p.stock===0?'status-red':p.stock<=p.reorderLevel?'status-amber':'status-green'"><i></i>{{p.stock===0?'Out of stock':p.stock<=p.reorderLevel?'Low stock':'In stock'}}</span></td></tr><tr v-if="!loading&&!dashboard?.products?.length"><td colspan="6" class="empty-row">No products yet. Add products to see them here.</td></tr><tr v-if="loading"><td colspan="6" class="empty-row">Loading inventoryâ€¦</td></tr></tbody></table></div></article><article class="card activity-card"><div class="card-header"><div><h2>Recent activity</h2><p>Latest inventory movements</p></div><button class="dots"><MoreHorizontal :size="18"/></button></div><div v-if="dashboard?.movements?.length" class="activity-list"><div v-for="m in dashboard.movements" :key="m.title+m.time" class="activity-item"><div class="activity-icon" :class="m.kind"><component :is="m.kind==='in'?'ArrowDownLeft':'ArrowUpRight'" :size="15"/></div><div class="activity-copy"><b>{{m.title}}</b><span>{{m.subtitle}}</span><small>{{m.time}}</small></div><strong :class="m.kind">{{m.quantity}}</strong></div></div><div v-else class="activity-empty"><div class="empty-symbol"><Activity :size="21"/></div><b>Nothing to show yet</b><span>Inventory activity will appear here.</span></div><RouterLink class="activity-link" to="/inventory">View all activity <ArrowRight :size="14"/></RouterLink></article></div></template>
<script setup lang="ts">import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';import {useRouter} from 'vue-router';import {Chart,registerables} from 'chart.js';import {api} from '../services/api';import type {Dashboard} from '../types';import {RefreshCw,Plus,WifiOff,Package,Boxes,ShoppingCart,DollarSign,ArrowUpRight,AlertTriangle,ChevronDown,MoreHorizontal,ArrowRight,Activity} from 'lucide-vue-next';Chart.register(...registerables);const router=useRouter(),dashboard=ref<Dashboard|null>(null),loading=ref(true),error=ref(false),salesCanvas=ref<HTMLCanvasElement>(),donutCanvas=ref<HTMLCanvasElement>();let salesChart:Chart|undefined,donutChart:Chart|undefined;const userName=JSON.parse(localStorage.getItem('nexstock_user')||'{}').name?.split(' ')[0]||'Jordan';const dateLabel=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();const endDate=ref(new Date().toISOString().slice(0,10));const startDate=ref(new Date(Date.now()-29*86400000).toISOString().slice(0,10));const fmt=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),fmtNum=(n:number)=>new Intl.NumberFormat('en-US').format(n);const metrics=computed(()=>[{label:'Total products',value:fmtNum(dashboard.value?.totalProducts||0),change:'',caption:'active SKUs',icon:Package,tone:'blue'},{label:'Stock value',value:fmt(dashboard.value?.stockValue||0),change:'',caption:'across all locations',icon:Boxes,tone:'violet'},{label:'Total orders',value:fmtNum(dashboard.value?.totalOrders||0),change:'',caption:'in the last 12 months',icon:ShoppingCart,tone:'amber'},{label:'Total revenue',value:fmt(dashboard.value?.revenue||0),alert:`${dashboard.value?.lowStockCount||0} need attention`,caption:'low stock items',icon:DollarSign,tone:'green'}]);async function load(){loading.value=true;error.value=false;try{const {data}=await api.get<Dashboard>('/dashboard',{params:{startDate:startDate.value,endDate:endDate.value}});dashboard.value=data;await nextTick();drawCharts();}catch{error.value=true;}finally{loading.value=false;}}function drawCharts(){salesChart?.destroy();donutChart?.destroy();if(salesCanvas.value&&dashboard.value)salesChart=new Chart(salesCanvas.value,{type:'line',data:{labels:dashboard.value.salesLabels,datasets:[{data:dashboard.value.sales,borderColor:'#3974ed',backgroundColor:(ctx:any)=>{const c=ctx.chart.ctx,g=c.createLinearGradient(0,0,0,220);g.addColorStop(0,'rgba(37,99,235,.19)');g.addColorStop(1,'rgba(37,99,235,0)');return g},fill:true,tension:.4,pointRadius:0,pointHoverRadius:4,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:c=>fmt(c.parsed.y??0)}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{color:'#9aa3b2',font:{size:10}}},y:{grid:{color:'#eff1f5'},border:{display:false,dash:[4,4]},ticks:{color:'#9aa3b2',font:{size:10},callback:v=>'$'+Number(v)/1000+'k'},beginAtZero:true}}}});if(donutCanvas.value&&dashboard.value)donutChart=new Chart(donutCanvas.value,{type:'doughnut',data:{labels:dashboard.value.categories.map(c=>c.name),datasets:[{data:dashboard.value.categories.map(c=>c.value),backgroundColor:dashboard.value.categories.map(c=>c.color),borderWidth:0,spacing:3,borderRadius:5,hoverOffset:3}]},options:{cutout:'75%',plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.label}: ${c.parsed}%`}}}}});}const updateHandler=()=>load();onMounted(()=>{load();window.addEventListener('nexstock-update',updateHandler)});onBeforeUnmount(()=>{window.removeEventListener('nexstock-update',updateHandler);salesChart?.destroy();donutChart?.destroy();});</script>
